            setupGPSPositions();
        }
    }

    public enum SensorStatus implements ITranslatableEnum {
        OK,
        MISSING_GPS,
        MISSING_UPGRADE,
        NO_SENSOR;

        @Override
        public String getTranslationKey() {
            return "pneumaticcraft.gui.universalSensor.status." + toString().toLowerCase(Locale.ROOT);
        }
    }
