    private static final Set<Block> MC181565_BLOCKS = Set.of(
            Blocks.AMETHYST_CLUSTER,
            Blocks.CANDLE,
            Blocks.LILY_PAD,
            Blocks.BIG_DRIPLEAF,
            Blocks.POINTED_DRIPSTONE,
            Blocks.TURTLE_EGG,
            Blocks.AZALEA,
            Blocks.HONEY_BLOCK
    );
    private static boolean checkMC181565kludge(Block block) {
        return MC181565_BLOCKS.contains(block);
    }

