    public static boolean ensureSlotsEmpty(IItemHandler handler, int required) {
        int nFree = 0;
        for (int i = 0; i < handler.getSlots(); i++) {
            if (handler.getStackInSlot(i).isEmpty() && ++nFree >= required) {
                return true;
            }
        }
        return false;
    }
