        SpiritJob job = this.getJob().get();
        Brain<SpiritEntity> brain = Brain.provider(job.getMemoryTypes(), job.getSensorTypes(), entity -> job.getActivityData())
                .makeBrain(this, packedBrain);
        job.handleAdditionalBrainSetup(brain);
        return brain;
    }

